1	// ============================================================================
2	// BNS Server - Channel 기반 HTTP 서버 (in-process)
3	// ============================================================================
4	// rpc.fl의 Channel을 HTTP 요청/응답으로 확장
5	
6	use concurrent;
7	use bns_models;
8	use bns_http;
9	use bns_handlers;
10	
11	// === 전역 채널 (클라이언트 ↔ 서버 통신) ===
12	let g_request_channel: concurrent.Channel;
13	let g_response_channel: concurrent.Channel;
14	let g_server_running: bool = false;
15	
16	// === 서버 초기화 ===
17	fn init_bns_server() {
18	    g_request_channel = concurrent.channel_new(64);
19	    g_response_channel = concurrent.channel_new(64);
20	    g_server_running = true;
21	}
22	
23	// === 서버 루프 (메인 진입점) ===
24	fn bns_server_loop() {
25	    init_bns_server();
26	
27	    println("🚀 BNS Server started");
28	    println("Listening on localhost:28080 (in-process Channel)");
29	    println("");
30	    println("Endpoints:");
31	    println("  GET  /api/status   - 프로젝트 상태");
32	    println("  GET  /api/gogs     - Gogs 커밋");
33	    println("  GET  /api/feed     - Server-Sent Events");
34	    println("  GET  /api/db       - DB 상태");
35	    println("");
36	
37	    let request_count = 0;
38	
39	    // 단순 요청 처리 루프 (협동 스케줄링)
40	    loop {
41	        // 요청 수신 (논블로킹)
42	        let request_str = concurrent.channel_recv(g_request_channel, 0);
43	
44	        if len(request_str) > 0 {
45	            request_count = request_count + 1;
46	
47	            // HTTP 요청 파싱
48	            let req = bns_http.parse_http_request(request_str);
49	
50	            println("[" + to_string(request_count) + "] " + req.method + " " + req.path);
51	
52	            // 핸들러 호출
53	            let response = bns_handlers.handle_request(req);
54	
55	            // HTTP 응답 형식화
56	            let response_str = bns_http.format_http_response(response);
57	
58	            // 응답 전송
59	            concurrent.channel_send(g_response_channel, response_str);
60	        }
61	
62	        // 협동 양보 (다른 작업에 CPU 할당)
63	        if request_count % 10 == 0 {
64	            // 간단한 yield 시뮬레이션 (실제 구현에서는 sys_yield 필요)
65	        }
66	    }
67	}
68	
69	// === 클라이언트 API: 요청 전송 ===
70	fn send_http_request(method: string, path: string, body: string) -> string {
71	    // 요청 구성 (간단한 HTTP 요청)
72	    let request = method + " " + path + " HTTP/1.1\r\n";
73	    request = request + "Host: localhost:28080\r\n";
74	    request = request + "Content-Type: application/json\r\n";
75	
76	    if len(body) > 0 {
77	        request = request + "Content-Length: " + to_string(len(body)) + "\r\n";
78	    }
79	
80	    request = request + "\r\n";
81	    if len(body) > 0 {
82	        request = request + body;
83	    }
84	
85	    // 요청 전송
86	    concurrent.channel_send(g_request_channel, request);
87	
88	    // 응답 수신 (폴링, max 100 tick)
89	    let i = 0;
90	    let response = "";
91	
92	    for i = 0; i < 100; i = i + 1 {
93	        response = concurrent.channel_recv(g_response_channel, 0);
94	
95	        if len(response) > 0 {
96	            break;
97	        }
98	
99	        // 짧은 대기 (실제로는 nanosleep 필요)
100	    }
101	
102	    return response;
103	}
104	
105	// === 테스트: 모든 엔드포인트 호출 ===
106	fn test_all_endpoints() {
107	    println("\n=== Testing All Endpoints ===\n");
108	
109	    // 1. /api/status
110	    println("GET /api/status");
111	    let status_resp = send_http_request("GET", "/api/status", "");
112	    println(status_resp);
113	    println("");
114	
115	    // 2. /api/gogs
116	    println("GET /api/gogs");
117	    let gogs_resp = send_http_request("GET", "/api/gogs", "");
118	    println(gogs_resp);
119	    println("");
120	
121	    // 3. /api/db
122	    println("GET /api/db");
123	    let db_resp = send_http_request("GET", "/api/db", "");
124	    println(db_resp);
125	    println("");
126	
127	    // 4. /api/feed (SSE)
128	    println("GET /api/feed");
129	    let feed_resp = send_http_request("GET", "/api/feed", "");
130	    println(feed_resp);
131	    println("");
132	
133	    // 5. /
134	    println("GET /");
135	    let root_resp = send_http_request("GET", "/", "");
136	    println(root_resp);
137	    println("");
138	}
