140	// === 헬퍼: 정수를 문자열로 ===
141	fn to_string(n: i32) -> string {
142	    if n == 0 {
143	        return "0";
144	    }
145	
146	    let negative = false;
147	    if n < 0 {
148	        negative = true;
149	        n = 0 - n;
150	    }
151	
152	    let result = "";
153	    let temp = n;
154	
155	    for temp > 0 {
156	        let digit = temp % 10;
157	        let ch = char_from_code(48 + digit);  // '0' = 48
158	        result = ch + result;
159	        temp = temp / 10;
160	    }
161	
162	    if negative {
163	        result = "-" + result;
164	    }
165	
166	    return result;
167	}
168	
169	// === Main ===
170	fn main() {
171	    // 서버 시작 (별도 스레드 필요 - 여기서는 간단히 테스트)
172	    init_bns_server();
173	
174	    // 테스트 모드: 몇 가지 엔드포인트 호출
175	    test_all_endpoints();
176	}
