6	module bns_http {
7	    use bns_models;
8	
9	    // === HTTP 파싱 ===
10	    // 요청 문자열: "GET /api/status HTTP/1.1\r\nHost: localhost\r\n\r\n{}"
11	    func parse_http_request(raw_request: string) -> bns_models.HttpRequest {
12	        let req: bns_models.HttpRequest;
13	        req.headers = make([string], 0);
14	
15	        if len(raw_request) == 0 {
16	            req.method = "INVALID";
17	            return req;
18	        }
19	
20	        // 라인 분리
21	        let lines = split_lines(raw_request);
22	        if len(lines) == 0 {
23	            req.method = "INVALID";
24	            return req;
25	        }
26	
27	        // 첫 줄 파싱: "GET /api/status HTTP/1.1"
28	        let first_line = lines[0];
29	        let parts = split_by_space(first_line);
30	
31	        if len(parts) >= 2 {
32	            req.method = parts[0];      // "GET", "POST", ...
33	            let path_with_query = parts[1];
34	
35	            // 경로와 쿼리 분리
36	            let qmark_idx = index_of(path_with_query, "?");
37	            if qmark_idx >= 0 {
38	                req.path = substring(path_with_query, 0, qmark_idx);
39	                req.query = substring(path_with_query, qmark_idx, len(path_with_query));
40	            } else {
41	                req.path = path_with_query;
42	                req.query = "";
43	            }
44	        }
45	
46	        // 헤더 파싱
47	        let i = 1;
48	        let body_start = -1;
49	
50	        for i = 1; i < len(lines); i = i + 1 {
51	            let line = lines[i];
52	
53	            // 빈 줄 = 헤더 끝
54	            if len(line) == 0 {
55	                body_start = i + 1;
56	                break;
57	            }
58	
59	            // 헤더 추가
60	            req.headers.push(line);
61	        }
62	
63	        // 바디 파싱
64	        if body_start >= 0 && body_start < len(lines) {
65	            let body_lines = make([string], 0);
66	            let j = body_start;
67	            for j = body_start; j < len(lines); j = j + 1 {
68	                body_lines.push(lines[j]);
69	            }
70	            req.body = join_strings(body_lines, "\n");
71	        }
72	
73	        return req;
74	    }
