76	    // === HTTP 응답 형식화 ===
77	    // 반환: HTTP/1.1 200 OK\r\nContent-Type: ...\r\n\r\n{body}
78	    func format_http_response(resp: bns_models.HttpResponse) -> string {
79	        let status_line = "";
80	        if resp.status_code == 200 {
81	            status_line = "HTTP/1.1 200 OK";
82	        } else if resp.status_code == 404 {
83	            status_line = "HTTP/1.1 404 Not Found";
84	        } else if resp.status_code == 500 {
85	            status_line = "HTTP/1.1 500 Internal Server Error";
86	        } else {
87	            status_line = "HTTP/1.1 400 Bad Request";
88	        }
89	
90	        let result = status_line + "\r\n";
91	        result = result + "Content-Type: " + resp.content_type + "\r\n";
92	        result = result + "Connection: keep-alive\r\n";
93	
94	        if resp.is_sse {
95	            result = result + "Cache-Control: no-cache\r\n";
96	        }
97	
98	        result = result + "\r\n";
99	        result = result + resp.body;
100	
101	        return result;
102	    }
