104	    // === 헬퍼 함수 ===
105	    @inline
106	    func split_lines(content: string) -> [string] {
107	        let lines = make([string], 0);
108	        let current = "";
109	        let i = 0;
110	        let len_val = len(content);
111	
112	        for i = 0; i < len_val; i = i + 1 {
113	            let ch_code = char_at(content, i);
114	
115	            if ch_code == 10 {  // '\n'
116	                // \r 제거
117	                if len(current) > 0 && char_at(current, len(current) - 1) == 13 {
118	                    current = substring(current, 0, len(current) - 1);
119	                }
120	                lines.push(current);
121	                current = "";
122	            } else {
123	                let ch = char_from_code(ch_code);
124	                current = current + ch;
125	            }
126	        }
127	
128	        if len(current) > 0 {
129	            if len(current) > 0 && char_at(current, len(current) - 1) == 13 {
130	                current = substring(current, 0, len(current) - 1);
131	            }
132	            lines.push(current);
133	        }
134	
135	        return lines;
136	    }
137	
138	    @inline
139	    func split_by_space(line: string) -> [string] {
140	        let parts = make([string], 0);
141	        let current = "";
142	        let i = 0;
143	        let len_val = len(line);
144	
145	        for i = 0; i < len_val; i = i + 1 {
146	            let ch_code = char_at(line, i);
147	
148	            if ch_code == 32 || ch_code == 9 {  // space or tab
149	                if len(current) > 0 {
150	                    parts.push(current);
151	                    current = "";
152	                }
153	            } else {
154	                let ch = char_from_code(ch_code);
155	                current = current + ch;
156	            }
157	        }
158	
159	        if len(current) > 0 {
160	            parts.push(current);
161	        }
162	
163	        return parts;
164	    }
165	
166	    @inline
167	    func index_of(haystack: string, needle: string) -> i32 {
168	        let i = 0;
169	        let j = 0;
170	        let h_len = len(haystack);
171	        let n_len = len(needle);
172	
173	        if n_len == 0 || n_len > h_len {
174	            return -1;
175	        }
176	
177	        for i = 0; i <= h_len - n_len; i = i + 1 {
178	            let found = true;
179	            for j = 0; j < n_len; j = j + 1 {
180	                if char_at(haystack, i + j) != char_at(needle, j) {
181	                    found = false;
182	                    break;
183	                }
184	            }
185	            if found {
186	                return i;
187	            }
188	        }
189	
190	        return -1;
191	    }
192	
193	    @inline
194	    func substring(s: string, start: i32, end: i32) -> string {
195	        let result = "";
196	        let i = start;
197	
198	        for i = start; i < end; i = i + 1 {
199	            let ch = char_from_code(char_at(s, i));
200	            result = result + ch;
201	        }
202	
203	        return result;
204	    }
205	
206	    @inline
207	    func join_strings(parts: [string], sep: string) -> string {
208	        let result = "";
209	        let i = 0;
210	
211	        for i = 0; i < len(parts); i = i + 1 {
212	            if i > 0 {
213	                result = result + sep;
214	            }
215	            result = result + parts[i];
216	        }
217	
218	        return result;
219	    }
