26	# git log -1 파싱: "abc1234 feat: 기능" → CommitRecord
27	func parse_git_log() (CommitRecord, error) {
28	  var record CommitRecord
29	
30	  # git log -1 --oneline
31	  cmd := exec.Command("git", "log", "-1", "--format=%H %s")
32	  output, err := cmd.Output()
33	  if err != nil {
34	    return record, err
35	  }
36	
37	  line := strings.TrimSpace(string(output))
38	  parts := strings.SplitN(line, " ", 2)
39	
40	  if len(parts) < 2 {
41	    return record, fmt.Errorf("invalid git log format")
42	  }
43	
44	  record.hash = parts[0]
45	  record.message = parts[1]
46	
47	  # 타임스탬프 추출: git log -1 --format=%aI
48	  cmd = exec.Command("git", "log", "-1", "--format=%aI")
49	  output, err = cmd.Output()
50	  if err == nil {
51	    record.timestamp = strings.TrimSpace(string(output))
52	  }
53	
54	  # --stat 파싱
55	  cmd = exec.Command("git", "log", "-1", "--stat")
56	  output, err = cmd.Output()
57	  if err == nil {
58	    parse_stat_output(string(output), &record)
59	  }
60	
61	  return record, nil
62	}
