65	func parse_git_status() GitStatus {
66	  cmd := exec.Command("git", "status", "--porcelain")
67	  output, err := cmd.Output()
68	
69	  var status GitStatus
70	  status.status = "clean"
71	  status.files = make([]string, 0)
72	
73	  if err != nil || len(output) == 0 {
74	    return status
75	  }
76	
77	  status.status = "dirty"
78	  lines := strings.Split(string(output), "\n")
79	
80	  for _, line := range lines {
81	    if len(line) > 3 {
82	      status.files = append(status.files, strings.TrimSpace(line[3:]))
83	    }
84	  }
85	
86	  return status
87	}
