89	# "3 files changed, 10 insertions(+), 5 deletions(-)" 파싱
90	func parse_stat_output(output string, record *CommitRecord) {
91	  lines := strings.Split(output, "\n")
92	
93	  for _, line := range lines {
94	    // "3 files changed, 10 insertions(+), 5 deletions(-)"
95	    if strings.Contains(line, "files changed") {
96	      parts := strings.Fields(line)
97	
98	      for i := 0; i < len(parts); i++ {
99	        if parts[i] == "files" && i > 0 {
100	          val, err := strconv.Atoi(parts[i-1])
101	          if err == nil {
102	            record.files_changed = val
103	          }
104	        }
105	
106	        if strings.HasPrefix(parts[i], "insertion") && i > 0 {
107	          val, err := strconv.Atoi(parts[i-1])
108	          if err == nil {
109	            record.insertions = val
110	          }
111	        }
112	
113	        if strings.HasPrefix(parts[i], "deletion") && i > 0 {
114	          val, err := strconv.Atoi(parts[i-1])
115	          if err == nil {
116	            record.deletions = val
117	          }
118	        }
119	      }
120	    }
121	  }
122	}
